-- Benchmark of the period performance comparison. The tenant value is the benchmark of the client view and the
-- default of every portfolio without its own value; the portfolio value overrides it. Deleting the instrument clears
-- the reference, so a portfolio then inherits the tenant default again.
ALTER TABLE tenant ADD COLUMN IF NOT EXISTS id_benchmark int(11) DEFAULT NULL
  COMMENT 'Benchmark of the client view and default of its portfolios';
ALTER TABLE portfolio ADD COLUMN IF NOT EXISTS id_benchmark int(11) DEFAULT NULL
  COMMENT 'Benchmark of this portfolio, overrides tenant.id_benchmark';

ALTER TABLE tenant DROP FOREIGN KEY IF EXISTS FK_Tenant_Benchmark;
ALTER TABLE tenant ADD CONSTRAINT FK_Tenant_Benchmark FOREIGN KEY (id_benchmark)
  REFERENCES securitycurrency (id_securitycurrency) ON DELETE SET NULL;
ALTER TABLE portfolio DROP FOREIGN KEY IF EXISTS FK_Portfolio_Benchmark;
ALTER TABLE portfolio ADD CONSTRAINT FK_Portfolio_Benchmark FOREIGN KEY (id_benchmark)
  REFERENCES securitycurrency (id_securitycurrency) ON DELETE SET NULL;

-- Daily budget of benchmark assignments per user (limit_type 1 = DAY_CUD), written by PerformanceBenchmarkResource.
INSERT IGNORE INTO entity_limit
 (limit_type, entity_name, relation_entity_name, count_scope, owner_scope, limit_value,
 created_by, last_modified_by, last_modified_time, version)
SELECT 1, 'PerformanceBenchmark', NULL, NULL, NULL, 100, 0, 0, CURRENT_TIMESTAMP, 0;

-- Fee models of PostFinance E-Trading and Migros Bank Standard from 1 January 2027. The commission rules become dated
-- periods: the shipped rules stay unchanged up to 2026-12-31, the new tariff applies from 2027-01-01. PostFinance also
-- gets the 2027 custody fee (tiered by custody value, charged at quarter end, no trading credits), so its 2024 custody
-- period now ends 2026-12-31. Only byte-identical shipped plans are replaced; custom documents and account overrides
-- remain untouched. Each plan exists in two byte variants: upgraded through V0_37_1 (FX section with CRLF) and
-- installed from the B0_38_0 baseline (LF). The FX section of either variant is kept as it is.
-- Templates are mirrored under resources/fee-models/commission/ and resources/fee-models/custody/postfinance.yaml.
UPDATE trading_platform_plan SET fee_model_yaml = CONCAT(CONVERT( USING utf8mb4),
  SUBSTRING(fee_model_yaml, LOCATE(CONCAT(CHAR(10), 'custody:'), fee_model_yaml) + 1))
WHERE SHA2(fee_model_yaml, 256) IN ('36c1599f84b2d64b43643a7a89717f0dbedf59b5956af7778e5b37406d445f36', 'f605a07f89eae842230a8bd443f981e73b964f21335d1bb2eb3e56f64c6176c7');

UPDATE trading_platform_plan SET fee_model_yaml = CONCAT(CONVERT( USING utf8mb4),
  CONVERT( USING utf8mb4),
  SUBSTRING(fee_model_yaml, LOCATE(CONCAT(CHAR(10), 'fx:'), fee_model_yaml)))
WHERE SHA2(fee_model_yaml, 256) IN ('81dbbac3d40e00c694405ad90d7a7dc3920b15254317fc3269c2117781f284af', 'cb21fffde995657d71523448b14e82c5eea835285843d8ea0b6850e43772dbf0');
